.ledger-title{padding:7px 10px;background:var(--head);border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px}.summary{display:grid;grid-template-columns:repeat(6,1fr);border-bottom:1px solid var(--line)}.metric{padding:8px 10px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric .label{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.35px}.metric .value{font-size:17px;font-weight:800;white-space:nowrap;margin-top:2px;font-variant-numeric:tabular-nums}.book-note{padding:6px 10px;font-size:10px;color:var(--muted);border-bottom:1px solid var(--line2);background:#fcfcfd}.recon{display:grid;grid-template-columns:minmax(0,1fr) 480px;border-bottom:1px solid var(--line)}.recon-table{width:100%;border-collapse:collapse}.recon-table td{padding:5px 10px;border-bottom:1px dotted #cfd4d9;font-variant-numeric:tabular-nums}.recon-table td:last-child{text-align:right;font-weight:750;white-space:nowrap}.recon-table tr.total td{border-top:2px solid #333;border-bottom:0;font-weight:900}.recon-form{border-left:1px solid var(--line);padding:9px 10px;background:#fbfcfd}.fields{display:grid;gap:6px}.hint{font-size:10px;color:var(--muted);margin-top:6px}.section{border-bottom:1px solid var(--line)}.denom-table{width:100%;border-collapse:collapse}.denom-table th{background:#f1f3f5;font-size:10px;text-transform:uppercase;letter-spacing:.35px;font-weight:800;color:#505963}.denom-table th,.denom-table td{padding:5px 8px;border-right:1px solid var(--line2);border-bottom:1px solid var(--line2)}.denom-table tbody tr:nth-child(even){background:#fafbfc}.denom-table .kind{width:110px;color:#69727d;font-size:11px}.denom-table .denom{font-weight:800}.denom-table .qty{width:130px}.denom-table .amount{text-align:right;font-weight:750;font-variant-numeric:tabular-nums;white-space:nowrap}.denom-total{border-top:2px solid #333;font-weight:900;background:#fafbfc}.denom-total td{padding:7px 8px}.cash-count-note{padding:6px 10px;font-size:10px;color:var(--muted);border-bottom:1px solid var(--line2)}.table-wrap{overflow:auto}table.table{width:100%;border-collapse:collapse;min-width:820px}.table th{background:#f1f3f5;font-size:10px;text-transform:uppercase;letter-spacing:.35px;font-weight:800;color:#505963;white-space:nowrap}.table th,.table td{padding:5px 8px;border-right:1px solid var(--line2);border-bottom:1px solid var(--line2);text-align:left;vertical-align:middle}.table tbody tr:nth-child(even){background:#fafbfc}.num{text-align:right!important;font-variant-numeric:tabular-nums;white-space:nowrap}.status{font-weight:800}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}.closing-badge{font-size:10px;font-weight:800;padding:2px 6px;border:1px solid var(--line);background:#fafbfc}.closing-badge.closed{color:var(--ok);border-color:#b8d9c1;background:#f2faf4}.closing-badge.open{color:var(--warn);border-color:#ead29b;background:#fffaf0}@media(max-width:1100px){.summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:950px){.summary{grid-template-columns:repeat(3,1fr)}.recon{grid-template-columns:1fr}.recon-form{border-left:0;border-top:1px solid var(--line)}}@media(max-width:600px){.wrap{margin:0;padding:0}.summary{grid-template-columns:1fr 1fr}.top{align-items:flex-start}.erp-nav a{padding:8px 9px}.denom-table{min-width:650px}}
