<div class="recon" id="reconciliation"><div><table class="recon-table"><tbody><tr><td>Saldo Buku / Expected Cash</td><td>Rp {{ number_format($summary['expected_cash'],0,',','.') }}</td></tr><tr><td>Cash Fisik</td><td id="physical-summary">Rp 0</td></tr><tr><td>Outstanding Gantungan</td><td>Rp {{ number_format($summary['hanging_amount'],0,',','.') }}</td></tr><tr class="total"><td>Accounted Cash = Cash Fisik + Gantungan</td><td id="accounted-cash">Rp {{ number_format($summary['hanging_amount'],0,',','.') }}</td></tr><tr class="total"><td>Selisih</td><td id="difference">Rp {{ number_format(-$summary['expected_cash'] + $summary['hanging_amount'],0,',','.') }}</td></tr></tbody></table></div><div class="recon-form"><div class="fields"><label>CATATAN<textarea name="notes" rows="2" placeholder="Catatan closing / selisih"></textarea></label><button type="submit">Reconcile & Closing</button></div><div class="hint">Closing tidak mengubah Buku Kas. Ia menyimpan hasil pemeriksaan: Saldo Buku ↔ Cash Fisik + Gantungan. Jika BALANCED, closing dapat difinalisasi.</div></div></div></form></div>
<div class="section" id="closing-history"><div class="ledger-title">Riwayat Closing Rp</div><div class="table-wrap"><table class="table"><thead><tr><th>No</th><th>Tanggal</th><th class="num">Expected</th><th class="num">Physical</th><th class="num">Gantungan</th><th class="num">Selisih</th><th>Status</th></tr></thead><tbody>@forelse($closings as $c)<tr><td>{{ $c->closing_no }}</td><td>{{ $c->closing_date?->format('Y-m-d') }}</td><td class="num">Rp {{ number_format($c->expected_cash,0,',','.') }}</td><td class="num">Rp {{ number_format($c->physical_cash,0,',','.') }}</td><td class="num">Rp {{ number_format($c->hanging_amount,0,',','.') }}</td><td class="num">Rp {{ number_format($c->difference,0,',','.') }}</td><td class="status">{{ $c->status }}</td></tr>@empty<tr><td colspan="7" style="text-align:center;color:#69727d;padding:14px">Belum ada closing.</td></tr>@endforelse</tbody></table></div></div>
</div></div>
<script>
(function(){
 const inputs=[...document.querySelectorAll('.denom-qty')];
 const totalEl=document.getElementById('cash-total');
 const physical=document.getElementById('physical_cash');
 const physicalSummary=document.getElementById('physical-summary');
 const accounted=document.getElementById('accounted-cash');
 const difference=document.getElementById('difference');
 const expected={{ (float)$summary['expected_cash'] }};
 const hanging={{ (float)$summary['hanging_amount'] }};
 const fmt=n=>'Rp '+Math.round(n).toLocaleString('id-ID');
 function recalc(){
   let total=0;
   inputs.forEach(i=>{let qty=Math.max(0,parseInt(i.value||0,10));let d=parseInt(i.dataset.denom,10);let line=qty*d;total+=line;i.closest('tr').querySelector('.line-total').textContent=fmt(line);});
   physical.value=total;
   totalEl.textContent=fmt(total);
   physicalSummary.textContent=fmt(total);
   const accountedValue=total+hanging;
   accounted.textContent=fmt(accountedValue);
   difference.textContent=fmt(accountedValue-expected);
 }
 inputs.forEach(i=>i.addEventListener('input',recalc));
 document.getElementById('closing-form').addEventListener('submit',function(){recalc();});
 recalc();
})();
</script>
</body></html>
